const items = $input.all();

return items.map(item => {
  let parsed;

  // Accès au contenu généré par l'IA (format standard OpenAI/Groq)
  const content = item.json.choices[0].message.content;

  try {
    parsed = JSON.parse(content);
  } catch (e) {
    console.error("Erreur de parsing JSON", e);
    parsed = {}; // Objet vide pour éviter de bloquer la suite
  }

  return {
    json: {
      experience_level: parsed.experience_level ?? "Unknown",
      skills: parsed.skills ?? "",
      certifications: parsed.certifications ?? ""
    }
  };
});

