const items = $input.all();

return items.map(item => {
  let company_size = "unknown";

  try {
    const content = item.json.choices[0].message.content;

    const cleaned = content
      .replace(/```json/g, '')
      .replace(/```/g, '')
      .trim();

    const parsed = JSON.parse(cleaned);

    // Handle both "size" and "company_size" field names
    const rawSize = parsed.company_size || parsed.size || "unknown";

    // Handle multiple values like "Small | Mid | Big" → take first
    const singleValue = rawSize.includes('|') 
      ? rawSize.split('|')[0].trim() 
      : rawSize.trim();

    // Normalize to exact vocabulary
    const validValues = ["startup", "small", "mid", "big", "unknown"];
    company_size = validValues.find(
      v => v.toLowerCase() === singleValue.toLowerCase()
    ) || "unknown";

  } catch(e) {
    company_size = "unknown";
  }

  return {
    json: {
      size: company_size  
    }
  };
});

const items = $input.all();

return items.map(item => {
  const d = item.json;

  // 1. Gestion de la date
  const rawDate = d.created || new Date().toISOString();
  const date = new Date(rawDate);
  const postingDate = date.toISOString().split('T')[0];

  // 2. Localisation (Adzuna area array)
  const areaArray = d.location?.area || [];
  const country = areaArray.length > 0 ? areaArray[0] : null;
  const area = areaArray.slice(1).join(', ') || null;
  const city = (d.location?.display_name || "").split(',')[0].trim() || null;

  // 3. Normalisation contrat
  let contractType = d.contract_time;
  if (contractType === 'full_time') contractType = 'Full-time';
  else if (contractType === 'part_time') contractType = 'Part-time';
  else contractType = 'Non-Précisé';

  // 4. Fonction utilitaire pour parser les listes (skills, certifs)
  const parseList = (raw) => {
    if (Array.isArray(raw)) return raw;
    if (!raw) return [];
    if (typeof raw === 'string') {
      return raw.split('\n')
        .map(s => s.replace(/^[-•*]\s*/, '').trim())
        .filter(s => s.length > 0);
    }
    return [];
  };

  // 5. Construction du document
  return {
    json: {
      job_id: "adzuna_" + d.id,
      source_name: "Adzuna",
      redirect_url: d.redirect_url || null,
      posting: {
        date: postingDate,
        year: date.getFullYear(),
        month: date.getMonth() + 1,
        day: date.getDate()
      },
      job_details: {
        title: d.title || null,
        role: null,
        contract_type: contractType,
        experience: {
          experience_level: d.experience_level || null,
          experience_raw: null,
          experience_extraction_method: "llm"
        },
        requirements: {
          // Correction ici : on utilise 'd' (l'item courant) et non $input.first()
          skills: parseList(d.skills),
          skills_extraction_method: "llm",
          certifications: parseList(d.certifications)
        }
      },
      company: {
        name: d.company?.display_name || null,
        size: d.size || null, // Correction ici
        profile: null
      },
      location: {
        city: city,
        country: country,
        area: area,
        latitude: d.latitude || null,
        longitude: d.longitude || null
      },
      category: {
        name: d.category?.label || "Autre",
        tag: d.category?.tag || null
      },
      salary: {
        min: d.salary_min || null,
        max: d.salary_max || null,
        range: null,
        is_predicted: d.salary_is_predicted === "1" || false
      }
    }
  };
});
